// CriteriaFilterPanel.js
import React from 'react';
import Slider from '@mui/material/Slider';
import Checkbox from '@mui/material/Checkbox';
import FormControlLabel from '@mui/material/FormControlLabel';

const CriteriaFilterPanel = ({ criteria, setCriteria }) => {
  const handleSliderChange = (name, minOrMax, value) => {
    setCriteria((prev) => ({
      ...prev,
      [name]: {
        ...prev[name],
        [minOrMax]: value,
      },
    }));
  };

  const handleCheckboxChange = (name) => {
    setCriteria((prev) => ({
      ...prev,
      [name]: {
        ...prev[name],
        enabled: !prev[name].enabled,
      },
    }));
  };

  return (
    <div>
      <h3>Filter Criteria</h3>

      {[
        { label: 'Tempo', key: 'tempo', range: [0, 20] },
        { label: 'Danceability', key: 'danceability', range: [0, 0.5] },
        { label: 'Energy', key: 'energy', range: [0, 0.5] },
        { label: 'Valence', key: 'valence', range: [0, 0.5] },
        { label: 'Acousticness', key: 'acousticness', range: [0, 0.5] },
        { label: 'Instrumentalness', key: 'instrumentalness', range: [0, 0.5] },
        { label: 'Liveness', key: 'liveness', range: [0, 0.5] },
      ].map(({ label, key, range }) => (
        <div key={key} style={{ marginBottom: '20px' }}>
          <FormControlLabel
            control={
              <Checkbox
                checked={criteria[key]?.enabled || false}
                onChange={() => handleCheckboxChange(key)}
              />
            }
            label={`Include ${label}`}
          />
          {criteria[key]?.enabled && (
            <>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <span>Min {label}</span>
                <Slider
                  value={criteria[key]?.min || 0}
                  onChange={(e, newValue) => handleSliderChange(key, 'min', newValue)}
                  min={-range[1]}
                  max={range[1]}
                  step={range[1] / 10}
                  style={{ width: '100px', marginLeft: '10px', marginRight: '10px' }}
                  valueLabelDisplay="auto"
                />
                <span>Max {label}</span>
                <Slider
                  value={criteria[key]?.max || 0}
                  onChange={(e, newValue) => handleSliderChange(key, 'max', newValue)}
                  min={-range[1]}
                  max={range[1]}
                  step={range[1] / 10}
                  style={{ width: '100px', marginLeft: '10px' }}
                  valueLabelDisplay="auto"
                />
              </div>
            </>
          )}
        </div>
      ))}
    </div>
  );
};

export default CriteriaFilterPanel;
